//! `async` generated by `mlirformat tblgen` (`async.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "async.gen.rs"]
mod r#async;

#[test]
fn async_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<r#async::Async>();
    common::Fixtures::check_dialect(&opt, "async");
}
